export function createGuideViews({shell,heading,esc,icon,isAdmin}){
 let current=null;
 const visible=()=>chapters.filter(c=>!c.admin||isAdmin());
 const figure=c=>c.image&&!c.video?`<figure class="guide-figure"><picture><source media="(max-width:650px)" srcset="assets/guide/${c.image}-movil.jpg"><img src="assets/guide/${c.image}.jpg" alt="Captura: ${esc(c.title)}" loading="lazy"></picture></figure>`:'';
 function index(){
  const list=visible();
  return `<div class="guide-intro panel"><p>Capítulos cortos para empezar a usar la aplicación. Si es tu primer día, empieza por el <button class="clear-link" data-guide="video-primera-factura">vídeo de un minuto</button>, sigue el orden y practica con una <button class="clear-link" data-guide="ejemplos">factura de ejemplo</button>.</p></div>${groups.map(([id,name])=>{const items=list.filter(c=>c.group===id);return items.length?`<section class="guide-group"><h2>${name}</h2><div class="guide-cards">${items.map(c=>`<button class="guide-card panel" data-guide="${c.id}"><span class="guide-number">${list.indexOf(c)+1}</span><strong>${esc(c.title)}</strong><small>${esc(c.summary)}</small></button>`).join('')}</div></section>`:'';}).join('')}`;
 }
 function chapter(c){
  const list=visible(),n=list.indexOf(c),prev=list[n-1],next=list[n+1];
  // A chapter can have a video (with download links), steps, a table or a glossary.
  const media=c.video?`<figure class="guide-video"><video controls preload="metadata" playsinline poster="assets/guide/${c.video}.jpg" src="assets/guide/${c.video}.mp4">Tu navegador no puede reproducir el vídeo.</video></figure><p class="guide-downloads"><a href="assets/guide/${c.video}.mp4" download="${esc(c.videoTitle||c.title)} - arquitecturadeguardia Finance.mp4">${icon('download')} Descargar el vídeo (MP4)</a><a href="assets/guide/${c.video}.srt" download>Subtítulos (.srt)</a></p>`:'';
  const body=media+(c.steps?`<ol class="guide-steps">${c.steps.map(s=>`<li>${s}</li>`).join('')}</ol>`:c.table?`<div class="tablewrap"><table class="guide-table"><thead><tr><th>Situación</th><th>Qué hacer</th></tr></thead><tbody>${c.table.map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join('')}</tbody></table></div>`:c.terms?`<dl class="guide-terms">${c.terms.map(([a,b])=>`<dt>${a}</dt><dd>${b}</dd>`).join('')}</dl>`:'');
  const action=c.action?(c.action[0]==='new'?`<button class="btn primary" data-action="new">${icon('plus')} ${c.action[1]}</button>`:`<button class="btn primary" data-nav="${c.action[0]}">${c.action[1]} ${icon('arrow')}</button>`):'';
  return `<button class="btn ghost guide-back" data-guide="">${icon('back')} Todos los capítulos</button><article class="guide-chapter panel"><span class="guide-number">${n+1}</span><h2>${esc(c.title)}</h2><p class="guide-why">${c.why||esc(c.summary)}</p>${body}${c.tip?`<div class="notice guide-tip"><strong>Consejo.</strong> ${c.tip}</div>`:''}${figure(c)}${action?`<div class="actions">${action}</div>`:''}</article><nav class="guide-pager" aria-label="Capítulos">${prev?`<button class="btn" data-guide="${prev.id}">${icon('back')} ${esc(prev.title)}</button>`:'<span></span>'}${next?`<button class="btn" data-guide="${next.id}">${esc(next.title)} ${icon('arrow')}</button>`:''}</nav>`;
 }
 function render(){const c=visible().find(x=>x.id===current);shell(heading('Guía de uso','Todo lo necesario para trabajar con la aplicación, paso a paso.')+(c?chapter(c):index()),'Guía');}
 document.addEventListener('click',event=>{const target=event.target.closest('[data-guide]');if(!target)return;current=target.dataset.guide||null;render();window.scrollTo(0,0);});
 return {render,open:id=>{current=id||null;}};
}
